probe_inputs.collection_script:
import hashlib,json,pathlib,platform,subprocess
root=pathlib.Path('/root/supervisor-test-final')
r=json.loads((root/'result.json').read_text())
r['environment']={'kernel':platform.release(),'architecture':platform.machine(),'os_release':pathlib.Path('/etc/os-release').read_text(),'isolation':'Disposable KVM guest; 4 vCPU, 6144 MiB RAM, 24 GiB overlay'}
r['runtime_files']={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [pathlib.Path('/usr/local/bin/runsc'),*pathlib.Path('/usr/local/bin/gvisor-bin').glob('*')] if p.is_file()}
r['inputs']={p.name:{'request':json.loads((p/'request.json').read_text()),'oci_config':json.loads((p/'config.json').read_text()),'runtime_stderr':(p/'stderr.log').read_text()} for p in root.iterdir() if (p/'config.json').is_file()}
r['runtime_state_after_tests']=subprocess.run(['/usr/local/bin/runsc','--root='+str(root/'state'),'list','--format=json'],check=True,capture_output=True,text=True).stdout
assert json.loads(r['runtime_state_after_tests']) in ([], None)
print(json.dumps(r,indent=2))
